const {
    Document, Packer, Paragraph, TextRun, HeadingLevel, AlignmentType,
    PageBreak, convertMillimetersToTwip, Table, TableRow, TableCell, WidthType,
    ShadingType, ImageRun, BorderStyle
} = require("docx");
const fs = require("fs");

const FONT = "Times New Roman";
const SIZE = 28; // 14pt
const LINE = 360; // 1.5 spacing

function body(text) {
    return new Paragraph({
        alignment: AlignmentType.JUSTIFIED,
        indent: { firstLine: 709 }, // ~1.25cm
        spacing: { line: LINE, after: 0 },
        children: [new TextRun({ text, font: FONT, size: SIZE })],
    });
}

function chapter(text) {
    return new Paragraph({
        alignment: AlignmentType.CENTER,
        spacing: { before: 480, after: 360, line: LINE },
        pageBreakBefore: true,
        children: [new TextRun({ text, font: FONT, size: SIZE, bold: true })],
    });
}

function h2(text) {
    return new Paragraph({
        alignment: AlignmentType.LEFT,
        spacing: { before: 360, after: 240, line: LINE },
        children: [new TextRun({ text, font: FONT, size: SIZE, bold: true })],
    });
}

function caption(text) {
    return new Paragraph({
        alignment: AlignmentType.CENTER,
        spacing: { before: 120, after: 240, line: LINE },
        children: [new TextRun({ text, font: FONT, size: SIZE, italics: true })],
    });
}

function image(path, widthPx, heightPx) {
    const data = fs.readFileSync(path);
    return new Paragraph({
        alignment: AlignmentType.CENTER,
        spacing: { before: 240, after: 60 },
        children: [new ImageRun({ data, transformation: { width: widthPx, height: heightPx }, type: "png" })],
    });
}

function cell(text, opts = {}) {
    return new TableCell({
        width: { size: opts.width || 2000, type: WidthType.DXA },
        shading: opts.header ? { type: ShadingType.CLEAR, fill: "DCE6F1" } : undefined,
        margins: { top: 60, bottom: 60, left: 100, right: 100 },
        children: [new Paragraph({
            alignment: opts.center ? AlignmentType.CENTER : AlignmentType.LEFT,
            spacing: { line: LINE },
            children: [new TextRun({ text: String(text), font: FONT, size: 22, bold: !!opts.header })],
        })],
    });
}

function table(headers, rows, widths) {
    const total = widths.reduce((a, b) => a + b, 0);
    return new Table({
        width: { size: total, type: WidthType.DXA },
        columnWidths: widths,
        rows: [
            new TableRow({ children: headers.map((h, i) => cell(h, { header: true, width: widths[i], center: true })) }),
            ...rows.map((r) => new TableRow({ children: r.map((v, i) => cell(v, { width: widths[i] })) })),
        ],
    });
}

function h3(text) {
    return new Paragraph({
        alignment: AlignmentType.LEFT,
        indent: { firstLine: 709 },
        spacing: { before: 240, after: 180, line: LINE },
        children: [new TextRun({ text, font: FONT, size: SIZE, bold: true, italics: true })],
    });
}

